INSERT INTO tb_docs (title,doc_type,"language","content",metadata,embedding,embedding_model,indexed,embedded_at,chunk_index,total_chunks,parent_doc_id,source_type,source_file,content_hash,created_at,updated_at) VALUES
	 ('성과평가 제도 안내','policy','ko','내용:
1. 평가 목적
당사의 성과평가 제도는 공정하고 투명한 평가를 통해 직원의 성장을 지원하고, 조직의 목표 달성에 기여하는 것을 목적으로 합니다.

2. 평가 주기
- 상반기 평가: 7월 (1월~6월 실적)
- 하반기 평가: 1월 (7월~12월 실적)
- 중간 피드백: 4월, 10월

3. 평가 항목
[업적 평가 (70%)]
- 개인 KPI 달성도
- 프로젝트 기여도
- 업무 품질

[역량 평가 (30%)]
- 직무 전문성
- 협업 및 커뮤니케이션
- 문제 해결 능력
- 리더십 (관리자급)

4. 평가 등급
- S등급: 탁월함 (상위 10%)
- A등급: 우수함 (상위 25%)
- B등급: 양호함 (상위 50%)
- C등급: 보통 (상위 75%)
- D등급: 미흡함 (하위 25%)

5. 평가 절차
① 자기 평가 작성 (평가 대상자)
② 1차 평가 (직속 상사)
③ 2차 평가 (차상위자)
④ 평가 조정 회의 (부서별)
⑤ 평가 확정 및 피드백 면담

6. 평가 결과 활용
- 연봉 인상률 결정
- 성과급 지급
- 승진 심사 자료
- 교육 및 경력개발 계획 수립','{}','[0.02379656,0.03902552,0.050777167,0.019659394,0.023419501,0.018465377,-0.055762716,-0.0011724152,0.03192426,-0.021680845,0.02289581,-0.024822997,-0.048179656,-0.06280113,0.01978508,-0.019764133,-0.029892335,-0.010416232,-0.02235117,-0.0032966405,0.027378613,0.023021497,0.004859861,0.012065861,0.0036318034,-0.0076511386,0.009342664,0.031107299,-0.04704848,-0.0640161,0.0058077434,-0.008342412,0.0011004076,-0.052494876,0.013186562,0.012746661,0.01099753,0.049436517,0.014181577,0.0019533709,-0.029138217,0.04931083,-0.011542169,-0.0329088,-0.027378613,0.025283845,0.014705269,0.0200574,0.034752194,0.0125267105,-0.01858059,0.08400018,0.024843944,0.0025516888,0.050860956,0.056726307,0.024948683,-0.039863426,-0.0072531328,-0.026163647,0.0279442,-0.023859404,0.021932216,0.033285856,-0.037831504,-0.042670418,-0.043403585,-0.03414471,-0.0028305547,-0.018695801,0.06393231,0.022414014,0.019942187,0.016601034,0.014579583,-0.045498352,0.08416776,-0.018360639,-0.025221001,0.04579162,-0.006027694,-0.012160126,-0.026854921,0.025200054,0.006200512,-0.039255947,-0.078218624,-0.076123856,-0.009971093,0.008232437,-0.037705816,0.012589553,-0.020224981,0.043403585,0.012484815,-0.04373875,-0.036805067,0.005383553,0.01126985,0.022246432,0.044157702,-0.01460053,-0.009248399,0.019282335,0.030667398,-0.014841429,0.0063052503,-0.009677826,-0.0012627521,-0.011332693,0.0002592275,0.04524698,-0.051698864,0.025116263,0.02281202,-0.03355818,0.015155643,0.011940176,-0.03716118,-0.04876619,-0.030311286,0.008850393,0.020235455,0.007373582,0.0050745746,-0.00024564425,0.011699277,-0.03487788,-0.022141693,-0.044032015,-0.020570617,-0.04432528,0.029180113,-0.026121752,-0.029892335,0.013375091,-0.003236416,0.00089878624,-0.017344676,-0.015375595,0.012673344,0.022434961,-0.0070227087,0.04120408,-0.031023508,-0.032385107,0.024592571,-0.01590976,-0.009861118,0.031379618,-0.011552643,-0.0073316866,-0.054505855,-0.013511251,0.017009513,0.01500901,-0.0074102404,0.04074323,-0.015721232,-0.0